'use strict'

// Generates ../mimetypes_gen.go from the mime package bundled with Hyperclay
// Local's `send`: Express answers a file's Content-Type through it, so the Go
// trial host has to answer from the same table, byte for byte.
//
//   node internal/managedtrial/testdata/mime/gen.cjs <hyperclay-local checkout> [out.go]
//
// `send` requires its own copy of `mime` (possibly nested under
// node_modules/send/node_modules), so the copy is resolved the way `send`
// resolves it rather than from the checkout's top level. `mime.define` walks the
// types file in order and later extensions win, so the table is built the same
// way, then sorted so the Go file is stable.

const fs = require('fs')
const path = require('path')

const checkout = process.argv[2]
const outPath = process.argv[3] || path.join(__dirname, '..', '..', 'mimetypes_gen.go')
if (!checkout) {
  process.stderr.write('usage: node gen.cjs <hyperclay-local checkout> [out.go]\n')
  process.exit(1)
}

const sendPath = require.resolve('send', { paths: [path.resolve(checkout)] })
const mimePath = require.resolve('mime', { paths: [sendPath] })
const mimeDir = path.dirname(mimePath)
const version = JSON.parse(fs.readFileSync(path.join(mimeDir, 'package.json'), 'utf8')).version
const typesPath = path.join(mimeDir, 'types.json')
const types = JSON.parse(fs.readFileSync(typesPath, 'utf8'))

const table = new Map()
for (const type of Object.keys(types)) {
  for (const ext of types[type]) table.set(ext, type)
}

const mime = require(mimePath)
const defaultType = mime.default_type
if (table.get('bin') !== defaultType) {
  throw new Error('the default type is not the type of bin: ' + defaultType)
}

const quote = (value) => JSON.stringify(value)
const lines = []
lines.push('//go:build managedtrial')
lines.push('')
lines.push('package managedtrial')
lines.push('')
lines.push('// Code generated by internal/managedtrial/testdata/mime/gen.cjs from ' + path.relative(path.resolve(checkout), typesPath).split(path.sep).join('/'))
lines.push('// (mime ' + version + '), the copy Hyperclay Local\'s `send` requires. DO NOT EDIT.')
lines.push('')
lines.push('const mimeDefaultType = ' + quote(defaultType))
lines.push('')
lines.push('var mimeTypes = map[string]string{')
const keys = [...table.keys()].sort()
const width = Math.max(...keys.map((ext) => quote(ext).length)) + 2
for (const ext of keys) {
  const key = quote(ext) + ':'
  lines.push('\t' + key.padEnd(width) + quote(table.get(ext)) + ',')
}
lines.push('}')
lines.push('')

fs.writeFileSync(outPath, lines.join('\n'))
process.stdout.write('wrote ' + table.size + ' types from mime ' + version + ' to ' + outPath + '\n')
